const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={type:'Sosyal Medya',duration:30,orientation:'vertical',source:'Yapay zekâ',profileId:'default',projectId:null,user:null,authRequired:false,profiles:[],training:null,trainingTimer:null,selected:0,playing:false,zoom:100,generatedScenes:null,voiceId:null,voiceAudio:null,musicId:null,musicVolume:.18,mediaLibraryMode:'stock',captionEnabled:true,captionStyle:'classic',captionPosition:'bottom',history:[],future:[],mediaBusy:false,scenes:[
 {title:'Şehir seninle yeniden ritim bulur.',sub:'Her adım, daha canlı bir geleceğe.',time:'0–7 sn'},
 {title:'Yeni fikirler aynı sokakta buluşur.',sub:'İlham her köşede.',time:'7–18 sn'},
 {title:'Geleceğin ritmini sen belirle.',sub:'Şimdi harekete geç.',time:'18–30 sn'}]};
function go(n){$$('.panel').forEach(p=>p.classList.remove('active'));$('#step-'+n).classList.add('active');$$('.step').forEach((s,i)=>s.classList.toggle('active',i<n));scrollTo(0,0)}
$$('[data-next]').forEach(b=>b.onclick=()=>go(b.dataset.next));
$$('.type-card').forEach(b=>b.onclick=()=>{$$('.type-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');state.type=b.dataset.type;$('#projectType').textContent=state.type});
$('#duration').oninput=e=>{state.duration=+e.target.value;$('#durationOut').textContent=state.duration+' saniye';$('#projectDuration').textContent=state.duration+' sn'};
$$('.source-toggle button').forEach(b=>b.onclick=()=>{$$('.source-toggle button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');state.source=b.dataset.source});
$$('.orientation-toggle button').forEach(b=>b.onclick=()=>{$$('.orientation-toggle button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');state.orientation=b.dataset.orientation});
$('#idea').oninput=e=>$('#ideaCount').textContent=e.target.value.length+' / 600';
$('#script').oninput=e=>{$('#charCount').textContent=e.target.value.length+' / 1800';state.generatedScenes=null};
$$('.example-prompts button').forEach(b=>b.onclick=()=>{$('#idea').value=b.textContent.replaceAll('“','').replaceAll('”','');$('#idea').dispatchEvent(new Event('input'));$('#idea').focus()});
function localScript(idea){const clean=idea.trim();return `Hazır mısın? ${clean}, hayatımıza yeni bir bakış getiriyor.\n\nFikrin merkezinde gerçek bir ihtiyaç var. Doğru yaklaşım, süreci daha kolay ve ulaşılabilir hâle getiriyor.\n\nŞimdi harekete geçme zamanı. ${clean} ile ilk adımı bugün at ve farkı keşfet.`}
$('#writeScript').onclick=async()=>{const idea=$('#idea').value.trim();if(idea.length<5)return toast('Önce fikrini biraz daha ayrıntılı yaz');const button=$('#writeScript');button.disabled=true;button.innerHTML='<span>✦</span> Kurgu DNA uygulanıyor…';try{let result;try{result=await api('/api/scripts/generate',{method:'POST',body:JSON.stringify({idea,type:state.type,duration:state.duration,tone:$('#tone').value,profileId:state.profileId})})}catch{result={script:localScript(idea),scenes:null,provider:'browser-fallback'}}$('#script').value=result.script;state.generatedScenes=result.scenes;$('#script').dispatchEvent(new Event('input'));if(result.scenes)state.generatedScenes=result.scenes;showEngine(result.provider,result.model);toast(result.editingProfile?`${result.editingProfile.name} kuralları uygulandı`:'Metin hazır; dilediğin gibi değiştirebilirsin')}finally{button.disabled=false;button.innerHTML='<span>✦</span> Metni oluştur'}};
function showEngine(provider,model){const badge=$('#engineStatus');const researched=provider==='wikipedia';const ai=provider==='ai'||researched;badge.classList.toggle('ai',ai);badge.classList.toggle('fallback',!ai);badge.innerHTML=`<i></i> ${researched?'Kaynaklı metin · Wikipedia':ai?`Yapay zekâ · ${model||'bağlı model'}`:'Ekonomik yerel metin motoru'}`}
async function checkEngine(){try{const health=await api('/api/health');state.imageEngine=health.imageEngine;showEngine(health.textEngine,health.model)}catch{$('#engineStatus').innerHTML='<i></i> Tarayıcı yedek metin motoru'}}
$('#voicePlay').onclick=async e=>{const text=$('#script').value.trim();if(!text)return toast('Önce metni oluştur');const button=e.currentTarget;if(state.voiceAudio){state.voiceAudio.currentTime=0;state.voiceAudio.play();button.textContent='◼ Oynatılıyor';state.voiceAudio.onended=()=>button.textContent='▶ Dinle';return}button.disabled=true;button.textContent='Ses üretiliyor…';try{const voice=await api('/api/voices/generate',{method:'POST',body:JSON.stringify({text})});state.voiceId=voice.id;state.voiceAudio=new Audio(voice.audioUrl);$('#voiceStatus').textContent='Türkçe · Render seslendirmesi hazır';state.voiceAudio.play();button.textContent='◼ Oynatılıyor';state.voiceAudio.onended=()=>button.textContent='▶ Dinle';toast('Seslendirme üretildi')}catch(error){if('speechSynthesis'in window){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='tr-TR';utterance.rate=.95;speechSynthesis.speak(utterance);$('#voiceStatus').textContent='Türkçe · Tarayıcı önizlemesi';button.textContent='◼ Oynatılıyor';utterance.onend=()=>button.textContent='▶ Üret & dinle';toast('Sunucu sesi yok; tarayıcı önizlemesi kullanılıyor')}else toast(error.message)}finally{button.disabled=false;if(!state.voiceAudio&&button.textContent==='Ses üretiliyor…')button.textContent='▶ Üret & dinle'}};
function scenesFromScript(){const script=$('#script').value.trim();if(!script)return null;const parts=script.split(/\n\s*\n|(?<=[.!?])\s+(?=[A-ZÇĞİÖŞÜ])/).filter(Boolean);const count=Math.min(5,Math.max(3,Math.ceil(state.duration/20)));const groups=Array.from({length:count},()=>[]);parts.forEach((part,index)=>groups[Math.min(count-1,Math.floor(index*count/parts.length))].push(part));const slice=state.duration/count;return groups.filter(g=>g.length).map((g,index)=>{const text=g.join(' ');const sentences=text.match(/[^.!?]+[.!?]?/g)||[text];return{title:sentences[0].trim(),sub:sentences.slice(1).join(' ').trim()||'Videoluk ile anlatını güçlendir.',time:`${Math.round(index*slice)}–${Math.round((index+1)*slice)} sn`}})}
function mediaPrompt(scene){return `${scene.title}. ${scene.sub||''}. Sinematik gerçekçi görüntü, doğal ışık, profesyonel kompozisyon, yazı ve logo olmasın.`}
async function findStock(scene,index=0){const queries=[scene.mediaQuery,scene.title,$('#idea').value].filter(Boolean);for(const query of queries){const data=await api(`/api/media/search?q=${encodeURIComponent(query)}&orientation=${state.orientation}`);if(data.results?.length)return data.results[index%data.results.length]}throw new Error('Uygun stok medya bulunamadı')}
async function createAiMedia(scene){return api('/api/images/generate',{method:'POST',body:JSON.stringify({prompt:scene.prompt||mediaPrompt(scene),orientation:state.orientation})})}
async function prepareSceneMedia(scene,index){scene.mediaStatus='loading';renderScenes();try{if(state.source==='Yapay zekâ'){try{scene.media=await createAiMedia(scene);scene.mediaSource='ai'}catch{scene.media=await findStock(scene,index);scene.mediaSource='stock-fallback'}}else{scene.media=await findStock(scene,index);scene.mediaSource='stock'}scene.mediaStatus='ready'}catch(error){scene.mediaStatus='failed';scene.mediaError=error.message}renderScenes();return scene}
async function prepareAllMedia(button){state.mediaBusy=true;for(let index=0;index<state.scenes.length;index++){button.innerHTML=`Medya hazırlanıyor ${index+1}/${state.scenes.length} <span>···</span>`;await prepareSceneMedia(state.scenes[index],index)}state.mediaBusy=false;const ready=state.scenes.filter(scene=>scene.media).length;toast(`${ready}/${state.scenes.length} sahneye medya yerleştirildi`);saveDraft()}
$('#generateBtn').onclick=async()=>{if(!$('#script').value.trim())return toast('Önce fikrinden bir metin oluştur');const b=$('#generateBtn');b.disabled=true;b.innerHTML='Kurgu planı hazırlanıyor <span>···</span>';const generated=state.generatedScenes;if(generated){const slice=state.duration/generated.length;state.scenes=generated.map((s,i)=>({title:s.title,sub:s.subtitle,mediaQuery:s.mediaQuery||s.title,prompt:mediaPrompt({title:s.title,sub:s.subtitle}),duration:Number(s.duration)||slice,speed:1,editingReason:s.editingReason||'',transition:s.transition||'',time:`${Math.round(i*slice)}–${Math.round((i+1)*slice)} sn`}))}else{state.scenes=(scenesFromScript()||state.scenes).map(scene=>({...scene,prompt:mediaPrompt(scene),duration:scene.duration||state.duration/(scenesFromScript()?.length||3),speed:1}))}normalizeSceneTimes();state.selected=0;state.history=[];state.future=[];const idea=$('#idea').value.trim();$('#projectName').textContent=idea.slice(0,52)||'Adsız Videoluk Projesi';prepareStudio();renderScenes();go(3);try{await prepareAllMedia(b)}finally{b.disabled=false;b.innerHTML='Sahneleri oluştur <span>✦</span>'}};
function prepareStudio(){const fmt=s=>`00:${String(s).padStart(2,'0')}`;const formats={vertical:{res:'1080 × 1920',ratio:'9 / 16'},horizontal:{res:'1920 × 1080',ratio:'16 / 9'},square:{res:'1080 × 1080',ratio:'1 / 1'}};const f=formats[state.orientation];$('#canvasResolution').textContent=f.res;$('#renderResolution').textContent=f.res;$('#canvasDuration').textContent=fmt(state.duration);$('#timelineDuration').textContent=fmt(state.duration);$('#rulerEnd').textContent=fmt(state.duration);$('#renderDuration').textContent=state.duration;$('#videoCanvas').style.aspectRatio=f.ratio;}
function normalizeSceneTimes(){const fallback=state.duration/Math.max(1,state.scenes.length);let cursor=0;state.scenes.forEach(scene=>{scene.duration=Math.max(1,Number(scene.duration)||fallback);const start=cursor;cursor+=scene.duration;scene.time=`${Math.round(start)}–${Math.round(cursor)} sn`;scene.speed=scene.speed||1});state.duration=Math.round(cursor);$('#timelineDuration').textContent=`00:${String(state.duration).padStart(2,'0')}`;$('#canvasDuration').textContent=`00:${String(state.duration).padStart(2,'0')}`;$('#rulerEnd').textContent=`00:${String(state.duration).padStart(2,'0')}`}
function renderScenes(){
 normalizeSceneTimes();
 $('#sceneCards').innerHTML=state.scenes.map((s,i)=>`<div class="scene-card ${i===state.selected?'selected':''} ${s.media?'has-media':''}" data-i="${i}"><div class="thumb" ${s.media?`style="background-image:linear-gradient(#0002,#0008),url('${s.media.thumbnail}')"`:''}>${escapeHtml(s.title)}</div><div class="scene-meta"><b>Sahne ${String(i+1).padStart(2,'0')}</b><span>${s.time}</span></div>${s.editingReason?`<small class="scene-decision" title="${escapeHtml(s.editingReason)}">◈ ${escapeHtml(s.editingReason)}</small>`:''}</div>`).join('');
 $('#videoClips').innerHTML=state.scenes.map((s,i)=>`<div class="clip ${i===state.selected?'selected':''}" draggable="true" data-i="${i}" style="flex-grow:${s.duration}">Sahne ${i+1}<br>${s.time} · ${s.speed}×</div>`).join('');
 $$('[data-i]').forEach(x=>x.onclick=()=>selectScene(+x.dataset.i));
 $$('#videoClips .clip').forEach(clip=>{clip.ondragstart=e=>e.dataTransfer.setData('text/plain',clip.dataset.i);clip.ondragover=e=>e.preventDefault();clip.ondrop=e=>{e.preventDefault();const from=+e.dataTransfer.getData('text/plain'),to=+clip.dataset.i;if(from===to)return;remember();const [moved]=state.scenes.splice(from,1);state.scenes.splice(to,0,moved);state.selected=to;renderScenes();toast('Sahne sırası değiştirildi')}});
 const s=state.scenes[state.selected]; if(s){$('#canvasTitle').textContent=s.title;$('#canvasSubtitle').textContent=s.sub;$('#captionPreview').textContent=s.sub;$('#sceneTitle').value=s.title;$('#sceneSubtitle').value=s.sub||'';$('#imagePrompt').value=s.prompt||mediaPrompt(s);$('#sceneMediaState').textContent=s.mediaStatus==='loading'?'Medya hazırlanıyor…':s.mediaStatus==='failed'?(s.mediaError||'Medya hazırlanamadı'):s.mediaSource==='ai'?'Yapay zekâ görseli hazır':s.mediaSource==='stock-fallback'?'AI bağlı değil · stok medya kullanıldı':s.media?'Stok medya hazır':'Bu sahne için medya seçilmedi';$('#videoCanvas').style.backgroundImage=s.media?.thumbnail?`linear-gradient(#061a1833,#061a1877),url("${String(s.media.thumbnail).replaceAll('"','')}")`:'';$('#videoCanvas').classList.toggle('has-scene-media',!!s.media)}
 saveDraft();
}
function selectScene(i){state.selected=i;renderScenes()}
function snapshot(){return structuredClone(state.scenes)}
function remember(value=snapshot()){state.history.push(value);if(state.history.length>30)state.history.shift();state.future=[]}
$('#addScene').onclick=()=>{remember();state.scenes.push({title:'Yeni sahne',sub:'Mesajını buraya ekle.',prompt:'',duration:5,speed:1});state.selected=state.scenes.length-1;renderScenes();toast('Yeni sahne eklendi')};
$('#deleteScene').onclick=()=>{if(state.scenes.length===1)return toast('En az bir sahne kalmalı');remember();state.scenes.splice(state.selected,1);state.selected=Math.max(0,state.selected-1);renderScenes();toast('Sahne silindi')};
function splitSelected(){const s=state.scenes[state.selected];if(!s)return;remember();const half=Math.max(1,(Number(s.duration)||2)/2);s.duration=half;state.scenes.splice(state.selected+1,0,{...structuredClone(s),duration:half,title:s.title+' · devam'});renderScenes();toast('Sahne ikiye bölündü')}
function duplicateSelected(){const s=state.scenes[state.selected];if(!s)return;remember();const copy=structuredClone(s);state.scenes.splice(state.selected+1,0,copy);state.selected++;renderScenes();toast('Sahne çoğaltıldı')}
function changeSelectedSpeed(){const speeds=[.75,1,1.25,1.5,2],scene=state.scenes[state.selected];if(!scene)return;remember();const old=Number(scene.speed)||1,next=speeds[(speeds.indexOf(old)+1)%speeds.length];scene.duration=(Number(scene.duration)||2)*old/next;scene.speed=next;$('#speedScene span').textContent=scene.speed+'×';renderScenes();toast(`Sahne hızı ${scene.speed}×`)}
function setPlayhead(seconds){const value=Math.max(0,Math.min(state.duration,seconds)),tracks=$('#timelineTracks'),width=tracks?.getBoundingClientRect().width||600;$('#currentTime').textContent='00:'+String(Math.floor(value)).padStart(2,'0');$('#timelinePlayhead').style.left=(144+(width-144)*(value/state.duration))+'px';return value}
let playTime=0;
function togglePlay(){state.playing=!state.playing;$('#canvasPlay').textContent=state.playing?'Ⅱ':'▶';$('#playOverlay').textContent=state.playing?'Ⅱ':'▶';if(state.playing){const int=setInterval(()=>{if(!state.playing||playTime>=state.duration){clearInterval(int);state.playing=false;playTime=0;setPlayhead(0);$('#canvasPlay').textContent='▶';return}playTime=setPlayhead(playTime+.25)},250)}}
$('#timelineRuler').onclick=e=>{const rect=e.currentTarget.getBoundingClientRect(),label=144;playTime=setPlayhead(((e.clientX-rect.left-label)/Math.max(1,rect.width-label))*state.duration)};
$('#canvasPlay').onclick=togglePlay;$('#playOverlay').onclick=togglePlay;$('#previewBtn').onclick=togglePlay;
$('#zoomIn').onclick=()=>{$('#zoomValue').textContent=(state.zoom=Math.min(150,state.zoom+10))+'%'};$('#zoomOut').onclick=()=>{$('#zoomValue').textContent=(state.zoom=Math.max(50,state.zoom-10))+'%'};
$('#undoBtn').onclick=()=>{if(!state.history.length)return toast('Geri alınacak işlem yok');state.future.push(snapshot());state.scenes=state.history.pop();state.selected=Math.min(state.selected,state.scenes.length-1);renderScenes();toast('İşlem geri alındı')};
$('#redoBtn').onclick=()=>{if(!state.future.length)return toast('İleri alınacak işlem yok');state.history.push(snapshot());state.scenes=state.future.pop();state.selected=Math.min(state.selected,state.scenes.length-1);renderScenes();toast('İşlem yeniden uygulandı')};
function bindSceneField(selector,key){const field=$(selector);field.onfocus=()=>field.dataset.before=JSON.stringify(state.scenes[state.selected]);field.oninput=()=>{const scene=state.scenes[state.selected];if(!scene)return;scene[key]=field.value;if(key==='prompt')scene.mediaQuery=field.value;$('#canvasTitle').textContent=scene.title;$('#canvasSubtitle').textContent=scene.sub;$('#captionPreview').textContent=scene.sub};field.onchange=()=>{const before=field.dataset.before;if(!before)return;const oldScenes=snapshot();oldScenes[state.selected]=JSON.parse(before);remember(oldScenes);renderScenes()}}
bindSceneField('#sceneTitle','title');bindSceneField('#sceneSubtitle','sub');bindSceneField('#imagePrompt','prompt');
$('#regenerateMedia').onclick=async()=>{if(state.mediaBusy)return;const scene=state.scenes[state.selected];if(!scene)return;remember();state.mediaBusy=true;const button=$('#regenerateMedia');button.disabled=true;button.textContent='Üretiliyor…';try{await prepareSceneMedia(scene,state.selected);toast('Sahne medyası yenilendi')}finally{state.mediaBusy=false;button.disabled=false;button.textContent='↻ Yeniden üret'}};
$('#changeMedia').onclick=()=>{openMedia();toast('Stok kütüphanesinden yeni medya seç')};
async function startRender(){
 $('#renderModal').classList.add('open');$('#renderModal').setAttribute('aria-hidden','false');
 $('#renderTitle').textContent='Render hazırlanıyor';$('#renderNote').textContent='Videoluk render motoruna bağlanıyor.';setRenderProgress(0);
 $('#downloadBtn').classList.add('disabled');$('#subtitleDownload').classList.add('disabled');
 try{
  const estimate=await api('/api/cost-estimate',{method:'POST',body:JSON.stringify(projectPayload())});
  $('#renderCost').textContent=estimate.totalCredits+' kredi';
  $('#renderNote').textContent=`Bakiyen ${estimate.availableCredits} kredi. Bu üretim ${estimate.totalCredits} kredi kullanacak.`;
  if(estimate.availableCredits<estimate.totalCredits)throw new Error(`Yetersiz kredi: ${estimate.totalCredits} gerekli, bakiyende ${estimate.availableCredits} var`);
  if(!state.voiceId){$('#renderNote').textContent='Seslendirme sunucuda hazırlanıyor.';try{const voice=await api('/api/voices/generate',{method:'POST',body:JSON.stringify({text:$('#script').value})});state.voiceId=voice.id;$('#voiceStatus').textContent='Türkçe · Render seslendirmesi hazır'}catch(error){$('#voiceStatus').textContent='Sunucu sesi yok · sessiz render';$('#renderNote').textContent='Sunucu sesi kullanılamadı; video sessiz hazırlanacak.'}}
  const project=await persistProject();
  const job=await api('/api/renders',{method:'POST',body:JSON.stringify({projectId:project.id})});
  $('#renderTitle').textContent='Videon işleniyor';pollRender(job.id);
 }catch(error){renderFailed(error.message)}
}
async function api(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json'},credentials:'same-origin',...options});const data=await response.json().catch(()=>({}));if(response.status===401&&url!=='/api/auth/login')showLogin();if(!response.ok)throw new Error(data.error||'Sunucu yanıt vermedi');return data}
function escapeHtml(value){return String(value||'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]))}
function currentProfile(){return state.profiles.find(profile=>profile.id===state.profileId)||state.profiles[0]}
function fillDna(profile){if(!profile)return;const rules=profile.rules||{};$('#dnaName').value=profile.name||'';$('#dnaDescription').value=profile.description||'';$('#dnaHook').value=rules.hookSeconds||3;$('#dnaShot').value=rules.averageShotSeconds||3.5;$('#dnaRhythm').value=rules.rhythm||'';$('#dnaNarrative').value=rules.narrativeStructure||'';$('#dnaTransition').value=rules.transitionPolicy||'';$('#dnaRequired').value=(rules.required||[]).join('\n');$('#dnaForbidden').value=(rules.forbidden||[]).join('\n');$('#dnaFeedbackCount').textContent=profile.feedbackCount?`${profile.feedbackCount} düzeltme örneği bu profile öğretilmiş.`:'Henüz kayıtlı düzeltme yok.'}
async function loadProfiles(){try{const data=await api('/api/editing-profiles');state.profiles=data.profiles||[];if(!state.profiles.some(profile=>profile.id===state.profileId))state.profileId=state.profiles[0]?.id||'default';$('#editingProfile').innerHTML=state.profiles.map(profile=>`<option value="${escapeHtml(profile.id)}">${escapeHtml(profile.name)}</option>`).join('');$('#editingProfile').value=state.profileId;const profile=currentProfile();$('#dnaSummary').innerHTML=profile?`<span class="dna-badge">◈ ${escapeHtml(profile.name)}</span> · ${(profile.rules.required||[]).length} zorunlu, ${(profile.rules.forbidden||[]).length} yasak kural`:'Kurgu profili yüklenemedi';fillDna(profile)}catch(error){$('#dnaSummary').textContent='Kurgu Beyni sunucu bağlantısı bekliyor'}}
$('#editingProfile').onchange=e=>{state.profileId=e.target.value;fillDna(currentProfile());const profile=currentProfile();$('#dnaSummary').innerHTML=`<span class="dna-badge">◈ ${escapeHtml(profile.name)}</span> · ${(profile.rules.required||[]).length} zorunlu, ${(profile.rules.forbidden||[]).length} yasak kural`};
$('#openDna').onclick=()=>{fillDna(currentProfile());$('#dnaModal').classList.add('open');$('#dnaModal').setAttribute('aria-hidden','false');loadTraining()};
$('#closeDna').onclick=()=>{$('#dnaModal').classList.remove('open');$('#dnaModal').setAttribute('aria-hidden','true');clearTimeout(state.trainingTimer)};
$('#saveDna').onclick=async()=>{const button=$('#saveDna');button.disabled=true;try{const profile=await api('/api/editing-profiles',{method:'POST',body:JSON.stringify({id:state.profileId,name:$('#dnaName').value,description:$('#dnaDescription').value,rules:{hookSeconds:+$('#dnaHook').value,averageShotSeconds:+$('#dnaShot').value,rhythm:$('#dnaRhythm').value,narrativeStructure:$('#dnaNarrative').value,transitionPolicy:$('#dnaTransition').value,required:$('#dnaRequired').value.split('\n').filter(Boolean),forbidden:$('#dnaForbidden').value.split('\n').filter(Boolean)}})});toast(`${profile.name} kaydedildi`);await loadProfiles()}catch(error){toast(error.message)}finally{button.disabled=false}};
$('#teachDna').onclick=async()=>{const note=$('#dnaFeedback').value.trim();if(note.length<5)return toast('Düzeltmenin nedenini biraz daha ayrıntılı yaz');const button=$('#teachDna');button.disabled=true;try{await api('/api/editing-feedback',{method:'POST',body:JSON.stringify({profileId:state.profileId,note,before:state.generatedScenes,after:{script:$('#script').value,scenes:state.scenes}})});$('#dnaFeedback').value='';toast('Kurgu düzeltmesi profile öğretildi');await loadProfiles()}catch(error){toast(error.message)}finally{button.disabled=false}};
function trainingStatusLabel(video){if(video.status==='ready')return `${Math.round(video.duration||0)} sn · ${video.cut_count||0} kesme · ort. ${Number(video.average_shot||0).toFixed(1)} sn`;if(video.status==='failed')return video.error||'Analiz başarısız';return video.status==='analyzing'?`Analiz ediliyor · %${video.progress||0}`:'Sırada bekliyor'}
function renderTraining(data){state.training=data;const minutes=Math.round((data.totalDurationSeconds||0)/60);$('#trainingSummary').innerHTML=data.total?`<b>${data.ready}/${data.total} video analiz edildi</b><span>${minutes} dk referans · ${data.processing} işlemde${data.failed?` · ${data.failed} hata`:''}</span>${data.suggestedAverageShotSeconds?`<em>Önerilen plan ritmi: ${data.suggestedAverageShotSeconds} sn</em>`:''}`:'<span>Henüz video yüklenmedi</span>';$('#trainingList').innerHTML=(data.videos||[]).slice(0,12).map(video=>`<div class="training-item ${video.status}"><i></i><div><b title="${escapeHtml(video.filename)}">${escapeHtml(video.filename)}</b><small>${escapeHtml(trainingStatusLabel(video))}</small></div></div>`).join('');$('#applyTraining').disabled=!data.ready;if(data.processing){clearTimeout(state.trainingTimer);state.trainingTimer=setTimeout(loadTraining,1800)}}
async function loadTraining(){try{renderTraining(await api(`/api/training-videos?profileId=${encodeURIComponent(state.profileId)}`))}catch(error){$('#trainingSummary').textContent=error.message}}
async function uploadTrainingFile(file,index,total){const response=await fetch(`/api/training-videos?profileId=${encodeURIComponent(state.profileId)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Video-Name':encodeURIComponent(file.name)},body:file});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`${file.name} yüklenemedi`);$('#trainingSummary').innerHTML=`<b>${index+1}/${total} yükleniyor</b><span>${escapeHtml(file.name)}</span>`}
$('#trainingFiles').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;$('#trainingFiles').disabled=true;try{for(let index=0;index<files.length;index++)await uploadTrainingFile(files[index],index,files.length);toast(`${files.length} video analiz sırasına alındı`);await loadTraining()}catch(error){toast(error.message);await loadTraining()}finally{$('#trainingFiles').disabled=false;e.target.value=''}};
$('#applyTraining').onclick=async()=>{const button=$('#applyTraining');button.disabled=true;button.textContent='Kurgu DNA güncelleniyor…';try{await api('/api/training/apply',{method:'POST',body:JSON.stringify({profileId:state.profileId})});await loadProfiles();await loadTraining();toast('Video analizleri Kurgu DNA’ya uygulandı')}catch(error){toast(error.message)}finally{button.textContent='Analizi Kurgu DNA’ya uygula';button.disabled=!state.training?.ready}};
function setRenderProgress(value){const progress=Math.max(0,Math.min(100,value||0));$('#renderProgress').textContent=progress+'%';$('#renderProgressBar').style.width=progress+'%'}
async function pollRender(id){try{const job=await api('/api/renders/'+id);setRenderProgress(job.progress);if(job.status==='completed'){renderCompleted(job);return}if(job.status==='failed'){renderFailed(job.error||'Render tamamlanamadı');return}$('#renderNote').textContent=job.status==='queued'?'Sıraya alındı.':'FFmpeg videoyu hazırlıyor.';setTimeout(()=>pollRender(id),1200)}catch(error){renderFailed(error.message)}}
function renderCompleted(job){$('#renderTitle').textContent='Videon hazır!';$('#renderMessage').innerHTML=`<span>${state.duration}</span> saniyelik video Videoluk sunucusunda işlendi.`;$('#renderIcon').textContent='✓';$('#renderNote').textContent='MP4 ve altyazı dosyaları indirilmeye hazır.';$('#downloadBtn').href=job.downloadUrl;$('#downloadBtn').classList.remove('disabled');$('#subtitleDownload').href=job.subtitleUrl;$('#subtitleDownload').classList.remove('disabled');setRenderProgress(100)}
function renderFailed(message){$('#renderTitle').textContent='Render başlatılamadı';$('#renderIcon').textContent='!';$('#renderNote').textContent=message+'. Yerel motor için server.py çalıştırılmalı.';setRenderProgress(0)}
$('#renderBtn').onclick=startRender;$('#closeModal').onclick=()=>$('#renderModal').classList.remove('open');
$('#downloadTopBtn').onclick=startRender;
$$('.assetbar button').forEach(button=>button.onclick=()=>{if(button.dataset.tab==='media'){openMedia()}else if(button.dataset.tab==='scenes')closeMedia();else if(button.dataset.tab==='audio'){$('#musicSelect').focus();toast('Timeline üzerindeki müzik kanalını kullanabilirsin')}});
function openMedia(){$('.scene-list').classList.add('show-media');$('#mediaQuery').value=state.scenes[state.selected]?.mediaQuery||state.scenes[state.selected]?.title||'';setMediaLibraryMode(state.mediaLibraryMode);if(state.mediaLibraryMode==='stock')$('#mediaQuery').focus()}
function closeMedia(){$('.scene-list').classList.remove('show-media')}
$('#closeMedia').onclick=closeMedia;
function setMediaLibraryMode(mode){state.mediaLibraryMode=mode;$$('[data-media-source]').forEach(button=>button.classList.toggle('selected',button.dataset.mediaSource===mode));$('#mediaSearch').hidden=mode!=='stock';$('#mediaUploadLabel').hidden=mode!=='uploads';$('#mediaCredit').hidden=mode!=='stock';if(mode==='uploads')loadMyMedia()}
$$('[data-media-source]').forEach(button=>button.onclick=()=>setMediaLibraryMode(button.dataset.mediaSource));
function mediaKind(file){if(file.type.startsWith('video/'))return'video';if(file.type.startsWith('image/'))return'image';if(file.type.startsWith('audio/'))return'audio';return''}
async function uploadMediaFile(file,kind=mediaKind(file)){if(!kind)throw new Error(`${file.name}: desteklenmeyen dosya türü`);if(file.size>500*1024*1024)throw new Error(`${file.name}: 500 MB sınırını aşıyor`);const response=await fetch('/api/uploads',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name),'X-Media-Kind':kind},credentials:'same-origin',body:file});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`${file.name} yüklenemedi`);return data}
function chooseUploadedMedia(item){if(!['image','logo','video'].includes(item.kind))return;remember();const scene=state.scenes[state.selected];scene.media=item;scene.mediaSource='upload';scene.mediaStatus='ready';renderScenes();closeMedia();toast(`${item.kind==='video'?'Video':'Görsel'} sahneye eklendi`)}
async function loadMyMedia(){const box=$('#mediaResults');box.innerHTML='<div class="media-empty">Yüklemelerin getiriliyor…</div>';try{const data=await api('/api/uploads');const assets=data.assets.filter(item=>item.kind!=='audio');box.innerHTML=assets.length?assets.map((item,index)=>`<div class="media-result uploaded"><button data-upload-media="${index}">${item.thumbnail?`<img src="${item.thumbnail}" alt="">`:'<span class="file-icon">▣</span>'}<span>${escapeHtml(item.filename)}</span></button><button class="delete-upload" data-delete-upload="${item.id}" title="Sil">×</button></div>`).join(''):'<div class="media-empty">Henüz görsel veya video yüklemedin.</div>';$$('[data-upload-media]').forEach(button=>button.onclick=()=>chooseUploadedMedia(assets[+button.dataset.uploadMedia]));$$('[data-delete-upload]').forEach(button=>button.onclick=async e=>{e.stopPropagation();if(!confirm('Bu medya kütüphaneden silinsin mi?'))return;await api(`/api/uploads/${button.dataset.deleteUpload}`,{method:'DELETE'});loadMyMedia()})}catch(error){box.innerHTML=`<div class="media-empty">${escapeHtml(error.message)}</div>`}}
$('#mediaUpload').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;const label=$('#mediaUploadLabel');label.classList.add('busy');try{for(const file of files)await uploadMediaFile(file);toast(`${files.length} medya dosyası yüklendi`);await loadMyMedia()}catch(error){toast(error.message)}finally{label.classList.remove('busy');e.target.value=''}};
$('#mediaSearch').onsubmit=async e=>{e.preventDefault();const query=$('#mediaQuery').value.trim();if(query.length<2)return;$('#mediaResults').innerHTML='<div class="media-empty">Stok kaynaklarında aranıyor…</div>';try{const data=await api(`/api/media/search?q=${encodeURIComponent(query)}&orientation=${state.orientation}`);$('#mediaCredit').textContent=data.provider==='wikimedia'?'Görseller Wikimedia Commons tarafından sağlanır':'Videolar Pexels tarafından sağlanır';$('#mediaCredit').href=data.provider==='wikimedia'?'https://commons.wikimedia.org':'https://www.pexels.com';$('#mediaResults').innerHTML=data.results.length?data.results.map((item,index)=>`<button class="media-result" data-media="${index}"><img src="${item.thumbnail}" alt=""><span>${item.creator} · ${item.mediaType==='image'?'Görsel':`${item.duration} sn video`}</span></button>`).join(''):'<div class="media-empty">Sonuç bulunamadı.</div>';$$('[data-media]').forEach(button=>button.onclick=()=>{remember();const item=data.results[+button.dataset.media];state.scenes[state.selected].media=item;state.scenes[state.selected].mediaSource='stock';state.scenes[state.selected].mediaStatus='ready';renderScenes();closeMedia();toast(item.mediaType==='image'?'Stok görsel sahneye eklendi':'Stok video sahneye eklendi')})}catch(error){$('#mediaResults').innerHTML=`<div class="media-empty">${error.message}</div>`}};
$('#captionEnabled').onchange=e=>{state.captionEnabled=e.target.checked;$('#captionPreview').style.display=e.target.checked?'block':'none';saveDraft()};
$('#captionPosition').onchange=e=>{state.captionPosition=e.target.value;$('#captionPreview').classList.remove('top','middle');if(e.target.value!=='bottom')$('#captionPreview').classList.add(e.target.value);saveDraft()};
$$('.caption-styles button').forEach(b=>b.onclick=()=>{state.captionStyle=b.dataset.captionStyle;$$('.caption-styles button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#captionPreview').classList.remove('bold','minimal');if(b.dataset.captionStyle!=='classic')$('#captionPreview').classList.add(b.dataset.captionStyle);saveDraft()});
async function loadMusicLibrary(){try{const data=await api('/api/uploads?kind=audio');$('#musicSelect').innerHTML='<option value="">Müzik yok</option>'+data.assets.map(item=>`<option value="${item.id}">${escapeHtml(item.filename)}</option>`).join('');$('#musicSelect').value=state.musicId||''}catch{}}
$('#musicUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const item=await uploadMediaFile(file,'audio');state.musicId=item.id;await loadMusicLibrary();$('#musicSelect').value=item.id;saveDraft();toast('Müzik timeline’a eklendi')}catch(error){toast(error.message)}finally{e.target.value=''}};
$('#musicSelect').onchange=e=>{state.musicId=e.target.value||null;saveDraft();toast(state.musicId?'Müzik seçildi':'Müzik kaldırıldı')};
$('#musicVolume').oninput=e=>{state.musicVolume=Number(e.target.value)/100;$('#musicVolumeOut').textContent=e.target.value+'%';saveDraft()};
function projectPayload(){return{id:state.projectId,title:$('#projectName').textContent,type:state.type,duration:state.duration,orientation:state.orientation,source:state.source,profileId:state.profileId,script:$('#script').value,voiceId:state.voiceId,musicId:state.musicId,musicVolume:state.musicVolume,captions:{enabled:state.captionEnabled,style:state.captionStyle,position:state.captionPosition,language:$('#captionLanguage').value},scenes:state.scenes.map(s=>({title:s.title,subtitle:s.sub,media:s.media||null,duration:s.duration,speed:s.speed,editingReason:s.editingReason||'',transition:s.transition||''}))}}
async function persistProject(){const project=await api('/api/projects',{method:'POST',body:JSON.stringify(projectPayload())});state.projectId=project.id;$('#saveState').textContent='Sunucuya kaydedildi';saveDraft(true);return project}
function queueServerSave(){if(!$('#script')?.value.trim()||!$('.panel.studio.active'))return;clearTimeout(queueServerSave.timer);queueServerSave.timer=setTimeout(()=>persistProject().catch(()=>{$('#saveState').textContent='Yerel taslak'}),1200)}
function saveDraft(skipServer=false){clearTimeout(saveDraft.timer);saveDraft.timer=setTimeout(()=>{try{localStorage.setItem('videoluk-draft',JSON.stringify({projectId:state.projectId,type:state.type,duration:state.duration,orientation:state.orientation,source:state.source,scenes:state.scenes,script:$('#script')?.value||'',idea:$('#idea')?.value||'',title:$('#projectName')?.textContent||'',musicId:state.musicId,musicVolume:state.musicVolume,captionEnabled:state.captionEnabled,captionStyle:state.captionStyle,captionPosition:state.captionPosition}));if($('#saveState')&&$('#saveState').textContent!=='Sunucuya kaydedildi')$('#saveState').textContent='Kaydedildi';if(!skipServer)queueServerSave()}catch{}},250)}
function restoreDraft(){try{const draft=JSON.parse(localStorage.getItem('videoluk-draft')||'null');if(!draft?.scenes?.length)return;Object.assign(state,{projectId:draft.projectId||null,type:draft.type||state.type,duration:draft.duration||state.duration,orientation:draft.orientation||state.orientation,source:draft.source||state.source,scenes:draft.scenes,musicId:draft.musicId||null,musicVolume:Number.isFinite(draft.musicVolume)?draft.musicVolume:.18,captionEnabled:draft.captionEnabled!==false,captionStyle:draft.captionStyle||'classic',captionPosition:draft.captionPosition||'bottom'});$('#script').value=draft.script||'';$('#idea').value=draft.idea||'';$('#projectName').textContent=draft.title||'Kayıtlı Videoluk Taslağı';$('#duration').value=state.duration;$('#durationOut').textContent=state.duration+' saniye';$('#projectDuration').textContent=state.duration+' sn';$('#projectType').textContent=state.type;$$('.type-card').forEach(button=>button.classList.toggle('selected',button.dataset.type===state.type));$$('.orientation-toggle button').forEach(button=>button.classList.toggle('selected',button.dataset.orientation===state.orientation));$$('.source-toggle button').forEach(button=>button.classList.toggle('selected',button.dataset.source===state.source));$('#captionEnabled').checked=state.captionEnabled;$('#captionPosition').value=state.captionPosition;$$('.caption-styles button').forEach(button=>button.classList.toggle('selected',button.dataset.captionStyle===state.captionStyle));$('#musicVolume').value=Math.round(state.musicVolume*100);$('#musicVolumeOut').textContent=Math.round(state.musicVolume*100)+'%';$('#script').dispatchEvent(new Event('input'));$('#idea').dispatchEvent(new Event('input'));state.selected=0;prepareStudio();renderScenes()}catch{}}
function showLogin(){if(!state.authRequired)return;$('#authModal').classList.add('open');$('#authModal').setAttribute('aria-hidden','false');setTimeout(()=>$('#loginEmail').focus(),100)}
function hideLogin(){$('#authModal').classList.remove('open');$('#authModal').setAttribute('aria-hidden','true')}
async function initializeAuth(){try{const auth=await api('/api/auth/status');state.authRequired=auth.required;state.user=auth.user||null;if(auth.user){$('#userMenu').textContent=(auth.user.name||auth.user.email||'V').slice(0,1).toUpperCase();$('#accountName').textContent=`${auth.user.name} · ${auth.user.email}`;$('#adminButton').hidden=auth.user.role!=='owner'}if(auth.required&&!auth.authenticated){showLogin();return}await Promise.all([loadProfiles(),loadMusicLibrary()])}catch(error){toast(error.message)}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=$('#loginButton');button.disabled=true;$('#loginError').textContent='';try{const auth=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});state.user=auth.user;$('#userMenu').textContent=(auth.user.name||'V').slice(0,1).toUpperCase();$('#accountName').textContent=`${auth.user.name} · ${auth.user.email}`;$('#adminButton').hidden=auth.user.role!=='owner';$('#loginPassword').value='';hideLogin();await Promise.all([loadProfiles(),loadMusicLibrary()]);toast('Videoluk stüdyosuna giriş yapıldı')}catch(error){$('#loginError').textContent=error.message}finally{button.disabled=false}};
async function loadProjects(){const list=$('#projectsList');list.innerHTML='<div class="projects-empty">Projeler yükleniyor…</div>';try{const data=await api('/api/projects');list.innerHTML=data.projects.length?data.projects.map(project=>`<div class="project-row"><div><h3>${escapeHtml(project.title)}</h3><small>Son kayıt: ${new Date(project.updated_at).toLocaleString('tr-TR')}</small></div><div class="project-actions"><button class="open-project" data-open-project="${project.id}">Aç</button><button data-duplicate-project="${project.id}">Çoğalt</button><button class="delete-project" data-delete-project="${project.id}">Sil</button></div></div>`).join(''):'<div class="projects-empty">Henüz kayıtlı proje yok.</div>';$$('[data-open-project]').forEach(button=>button.onclick=()=>openSavedProject(button.dataset.openProject));$$('[data-duplicate-project]').forEach(button=>button.onclick=async()=>{await api(`/api/projects/${button.dataset.duplicateProject}/duplicate`,{method:'POST',body:'{}'});toast('Proje çoğaltıldı');loadProjects();loadUsage()});$$('[data-delete-project]').forEach(button=>button.onclick=async()=>{if(!confirm('Bu proje ve tamamlanan render dosyaları silinsin mi?'))return;await api(`/api/projects/${button.dataset.deleteProject}`,{method:'DELETE'});if(state.projectId===button.dataset.deleteProject)state.projectId=null;toast('Proje silindi');loadProjects();loadUsage()})}catch(error){list.innerHTML=`<div class="projects-empty">${escapeHtml(error.message)}</div>`}}
function usageItem(label,used,limit,detail=''){const percent=Math.min(100,Math.round(used/Math.max(1,limit)*100));return`<div class="usage-item ${percent>=85?'warning':''}"><span>${label}<b>${detail||`${used} / ${limit}`}</b></span><div class="usage-bar"><i style="width:${percent}%"></i></div></div>`}
async function loadUsage(){try{const usage=await api('/api/usage');const storageUsed=(usage.storage.usedBytes/1024/1024).toFixed(0),storageLimit=(usage.storage.limitBytes/1024/1024/1024).toFixed(0);$('#usageCard').innerHTML=`<div class="usage-item credit-balance"><span>Kredi bakiyesi<b>${usage.credits} kredi</b></span><div class="usage-bar"><i style="width:100%"></i></div></div>`+usageItem('Projeler',usage.projects.used,usage.projects.limit)+usageItem('Bu ay render',usage.renders.used,usage.renders.limit)+usageItem('Depolama',usage.storage.usedBytes,usage.storage.limitBytes,`${storageUsed} MB / ${storageLimit} GB`)}catch(error){$('#usageCard').innerHTML=`<span>${escapeHtml(error.message)}</span>`}}
async function loadCreditPackages(){try{const data=await api('/api/credit-packages');$('#creditPackages').innerHTML=data.packages.map(item=>`<button class="credit-package" data-package="${item.id}" ${data.configured?'':'disabled'}><span><b>${escapeHtml(item.name)}</b><small>${item.credits} kredi</small></span><em>${item.price} TL</em></button>`).join('')+(data.configured?'':'<small class="media-empty">Kredi satın alma, iyzico anahtarları sunucuya girildiğinde açılacak.</small>');$$('[data-package]').forEach(button=>button.onclick=()=>{const item=data.packages.find(pack=>pack.id===button.dataset.package);$('#paymentPackageId').value=item.id;$('#paymentTitle').textContent=`${item.name} · ${item.credits} kredi · ${item.price} TL`;$('#projectsModal').classList.remove('open');$('#paymentModal').classList.add('open')})}catch(error){$('#creditPackages').innerHTML=`<small>${escapeHtml(error.message)}</small>`}}
function adminRow(values){return`<div class="admin-row">${values.map((value,index)=>index===0?`<b>${escapeHtml(value)}</b>`:`<span>${escapeHtml(value)}</span>`).join('')}</div>`}
async function loadAdmin(){const data=await api('/api/admin/overview'),m=data.metrics;$('#adminMetrics').innerHTML=[['KULLANICI',m.users],['PROJE',m.projects],['TAMAMLANAN',m.rendersCompleted],['AKTİF İŞ',m.rendersActive],['DEPOLAMA',(m.storageBytes/1024/1024).toFixed(0)+' MB'],['CİRO',Number(m.revenueTry).toLocaleString('tr-TR')+' TL']].map(item=>`<div class="admin-metric"><small>${item[0]}</small><b>${item[1]}</b></div>`).join('');$('#adminUsers').innerHTML=data.users.length?data.users.map(user=>adminRow([user.email,user.name,`${user.project_count} proje`,`${user.credits} kredi`])).join(''):'<div class="media-empty">Kullanıcı yok</div>';$('#adminRenders').innerHTML=data.renders.length?data.renders.map(render=>adminRow([render.title,render.email,render.status,`%${render.progress}`])).join(''):'<div class="media-empty">Render yok</div>';$('#adminPayments').innerHTML=data.payments.length?data.payments.map(payment=>adminRow([payment.email,`${payment.amount} ${payment.currency}`,`${payment.credits} kredi`,payment.status])).join(''):'<div class="media-empty">Ödeme yok</div>'}
$('#adminButton').onclick=async()=>{$('#projectsModal').classList.remove('open');$('#adminModal').classList.add('open');try{await loadAdmin()}catch(error){toast(error.message)}};$('#closeAdmin').onclick=()=>{$('#adminModal').classList.remove('open');$('#projectsModal').classList.add('open')};
$('#closePayment').onclick=()=>{$('#paymentModal').classList.remove('open');$('#projectsModal').classList.add('open')};
$('#paymentForm').onsubmit=async e=>{e.preventDefault();const button=$('#paymentButton');button.disabled=true;$('#paymentError').textContent='';try{const result=await api('/api/payments/iyzico/checkout',{method:'POST',body:JSON.stringify({packageId:$('#paymentPackageId').value,billing:{name:$('#billingName').value,surname:$('#billingSurname').value,gsmNumber:$('#billingPhone').value,identityNumber:$('#billingIdentity').value,address:$('#billingAddress').value,city:$('#billingCity').value}})});if(!result.paymentPageUrl)throw new Error('Ödeme sayfası alınamadı');location.href=result.paymentPageUrl}catch(error){$('#paymentError').textContent=error.message}finally{button.disabled=false}};
function applyProject(project){state.projectId=project.id;state.type=project.type||state.type;state.duration=Number(project.duration)||30;state.orientation=project.orientation||'vertical';state.source=project.source||'Stok görüntü';state.voiceId=project.voiceId||null;state.musicId=project.musicId||null;state.musicVolume=Number.isFinite(project.musicVolume)?project.musicVolume:.18;state.captionEnabled=project.captions?.enabled!==false;state.captionStyle=project.captions?.style||'classic';state.captionPosition=project.captions?.position||'bottom';state.scenes=(project.scenes||[]).map(scene=>({...scene,sub:scene.subtitle??scene.sub??'',speed:scene.speed||1}));$('#script').value=project.script||'';$('#projectName').textContent=project.title||'Videoluk Projesi';$('#musicSelect').value=state.musicId||'';$('#musicVolume').value=Math.round(state.musicVolume*100);$('#musicVolumeOut').textContent=Math.round(state.musicVolume*100)+'%';$('#script').dispatchEvent(new Event('input'));state.selected=0;prepareStudio();renderScenes();saveDraft(true);go(3)}
async function openSavedProject(id){try{const project=await api(`/api/projects/${id}`);applyProject(project);$('#projectsModal').classList.remove('open');toast('Proje açıldı')}catch(error){toast(error.message)}}
function newProject(){localStorage.removeItem('videoluk-draft');state.projectId=null;state.voiceId=null;state.musicId=null;state.musicVolume=.18;state.generatedScenes=null;state.scenes=[{title:'Yeni sahne',sub:'Fikrini yazarak başla.',duration:30,speed:1}];$('#idea').value='';$('#script').value='';$('#projectName').textContent='Adsız Videoluk Projesi';$('#musicSelect').value='';$('#musicVolume').value=18;$('#musicVolumeOut').textContent='18%';$('#projectsModal').classList.remove('open');go(1);renderScenes();toast('Yeni proje hazır')}
$('#openProjects').onclick=()=>{$('#projectsModal').classList.add('open');$('#projectsModal').setAttribute('aria-hidden','false');loadProjects();loadUsage();loadCreditPackages()};$('#userMenu').onclick=$('#openProjects').onclick;$('#closeProjects').onclick=()=>{$('#projectsModal').classList.remove('open');$('#projectsModal').setAttribute('aria-hidden','true')};$('#newProject').onclick=newProject;$('#logoutButton').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});state.user=null;$('#adminButton').hidden=true;$('#projectsModal').classList.remove('open');showLogin()};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
restoreDraft();renderScenes();
checkEngine();
initializeAuth();
const paymentResult=new URLSearchParams(location.search).get('payment');if(paymentResult){setTimeout(()=>{toast(paymentResult==='success'?'Ödeme onaylandı; kredilerin hesabına eklendi':'Ödeme tamamlanamadı')},500);history.replaceState({},'',location.pathname)}
